#!/usr/bin/env python3
"""Decode a base64 string passed as a command-line argument and write the
decoded text to /workspace/comment.txt."""

import base64
import sys


def main():
    if len(sys.argv) != 2:
        print("Usage: python decode.py <base64_string>", file=sys.stderr)
        sys.exit(1)

    encoded = sys.argv[1]
    try:
        decoded_bytes = base64.b64decode(encoded, validate=True)
    except (base64.binascii.Error, ValueError) as e:
        print(f"Error decoding base64: {e}", file=sys.stderr)
        sys.exit(1)

    decoded_text = decoded_bytes.decode("utf-8")

    with open("/workspace/comment.txt", "w", encoding="utf-8") as f:
        f.write(decoded_text)


if __name__ == "__main__":
    main()
